1	import "dotenv/config";
2	import express from "express";
3	import path from "path";
4	import helmet from "helmet";
5	import cors from "cors";
6	import cookieParser from "cookie-parser";
7	import rateLimit from "express-rate-limit";
8	import { createServer as createViteServer } from "vite";
9	
10	import { initDb } from "./server/db.js";
11	import { apiRouter } from "./server/routes.js";
12	import uploadRouter from "./server/upload.js";
13	import { runTopsisAllActive } from "./server/topsis.js";
14	import { logger } from "./server/logger.js";
15	
16	async function startServer() {
17	  if (process.env.NODE_ENV === "production") {
18	    if (!process.env.JWT_SECRET) { logger.error("JWT_SECRET is required in production"); process.exit(1); }
19	    if (!process.env.ADMIN_SECRET_KEY) { logger.error("ADMIN_SECRET_KEY is required in production"); process.exit(1); }
20	  }
21	
22	  initDb();
23	  const app = express();
24	  const PORT = parseInt(process.env.PORT || "3000", 10);
25	  const ALLOWED_ORIGINS = process.env.ALLOWED_ORIGINS?.split(",") || ["http://localhost:3000", "http://localhost:5173"];
26	
27	  app.use(helmet({
28	    contentSecurityPolicy: {
29	      directives: {
30	        defaultSrc: ["'self'"],
31	        scriptSrc: ["'self'", "'unsafe-inline'"],
32	        styleSrc: ["'self'", "'unsafe-inline'"],
33	        imgSrc: ["'self'", "data:", "https:", "blob:"],
34	        connectSrc: ["'self'", "https:", "w:"],
35	        fontSrc: ["'self'", "data:", "https:"],
36	        objectSrc: ["'none'"],
37	        mediaSrc: ["'self'"],
38	        frameSrc: ["'none'"],
39	        ...(process.env.NODE_ENV === "production" && { upgradeInsecureRequests: [] }),
40	      },
41	    },
42	    crossOriginEmbedderPolicy: false,
43	  }));
44	
45	  app.use(cors({
46	    origin: (origin, callback) => {
47	      if (!origin || ALLOWED_ORIGINS.includes(origin) || process.env.NODE_ENV !== "production") callback(null, true);
48	      else callback(new Error("CORS not allowed"));
49	    },
50	    credentials: true,
51	  }));
52	  app.use(cookieParser());
53	  app.use(express.json({ limit: "1mb" }));
54	
55	  const handler = (_req: any, res: any) => res.status(429).json({ message: "Terlalu banyak permintaan, silakan coba lagi nanti." });
56	  const loginLimiter = rateLimit({ windowMs: 60 * 1000, max: 10, standardHeaders: true, legacyHeaders: false, handler });
57	  const uploadLimiter = rateLimit({ windowMs: 60 * 1000, max: 10, standardHeaders: true, legacyHeaders: false, handler });
58	  const generalLimiter = rateLimit({ windowMs: 15 * 60 * 1000, max: 100, standardHeaders: true, legacyHeaders: false, handler });
59	
60	  // Per-user login rate limiting (5 attempts per email per minute)
61	  const loginAttempts = new Map<string, { count: number; resetAt: number }>();
62	  app.use("/api/auth/login", (req: any, res: any, next: any) => {
63	    const email = req.body?.email;
64	    if (!email) return next();
65	    const now = Date.now();
66	    const key = `login:${email}`;
67	    const entry = loginAttempts.get(key);
68	    if (entry && entry.resetAt > now) {
69	      if (entry.count >= 5) {
70	        return res.status(429).json({ message: "Terlalu banyak percobaan login. Silakan coba lagi dalam 1 menit." });
71	      }
72	      entry.count++;
73	    } else {
74	      loginAttempts.set(key, { count: 1, resetAt: now + 60000 });
75	    }
76	    // Cleanup old entries
77	    if (loginAttempts.size > 10000) {
78	      const cutoff = now - 120000;
79	      for (const [k, v] of loginAttempts) { if (v.resetAt < cutoff) loginAttempts.delete(k); }
80	    }
81	    next();
82	  }, loginLimiter);
83	  app.use("/api/upload", uploadLimiter);
84	  app.use("/api", generalLimiter);
85	
86	  app.get("/health", (_req, res) => {
87	    res.json({ status: "ok", uptime: process.uptime() });
88	  });
89	
90	  app.use("/uploads", express.static(path.join(process.cwd(), "public", "uploads")));
91	  app.use("/api", uploadRouter);
92	  app.use("/api", apiRouter);
93	
94	  // SSE endpoint for real-time notifications
95	  const sseClients = new Map<number, Set<any>>();
96	  app.get("/api/notifications/subscribe", (req, res) => {
97	    const userId = parseInt(req.query.user_id as string);
98	    if (!userId) { res.status(400).json({ message: "user_id required" }); return; }
99	    res.writeHead(200, {
100	      "Content-Type": "text/event-stream",
101	      "Cache-Control": "no-cache",
102	      Connection: "keep-alive",
103	      "X-Accel-Buffering": "no",
104	    });
105	    res.write("data: connected\n\n");
106	    if (!sseClients.has(userId)) sseClients.set(userId, new Set());
107	    sseClients.get(userId)!.add(res);
108	    const ping = setInterval(() => res.write(":ping\n\n"), 30000);
109	    req.on("close", () => {
110	      clearInterval(ping);
111	      sseClients.get(userId)?.delete(res);
112	    });
113	  });
114	
115	  // Helper to push notifications to connected SSE clients
116	  (global as any).notifyUser = (userId: number, data: any) => {
117	    sseClients.get(userId)?.forEach(res => res.write(`data: ${JSON.stringify(data)}\n\n`));
118	  };
119	
120	  runTopsisAllActive();
121	
122	  if (process.env.NODE_ENV !== "production") {
123	    const vite = await createViteServer({
124	      server: { middlewareMode: true },
125	      appType: "spa",
126	    });
127	    app.use(vite.middlewares);
128	  } else {
129	    const distPath = path.join(process.cwd(), "dist");
130	    app.use(express.static(distPath));
131	    app.get("*", (_req, res) => {
132	      res.sendFile(path.join(distPath, "index.html"));
133	    });
134	  }
135	
136	  app.use((_req, res) => {
137	    res.status(404).json({ message: "Endpoint tidak ditemukan" });
138	  });
139	
140	  app.use((err: Error, _req: express.Request, res: express.Response, _next: express.NextFunction) => {
141	    logger.error("Server error", { message: err.message, stack: err.stack });
142	    res.status(500).json({ message: "Terjadi kesalahan server" });
143	  });
144	
145	  const server = app.listen(PORT, "0.0.0.0", () => {
146	    logger.info(`Server running on http://localhost:${PORT}`, { port: PORT, env: process.env.NODE_ENV || "development" });
147	  });
148	
149	  const shutdown = (signal: string) => {
150	    logger.info(`${signal} received — shutting down...`);
151	    server.close(() => process.exit(0));
152	  };
153	  process.on("SIGTERM", () => shutdown("SIGTERM"));
154	  process.on("SIGINT", () => shutdown("SIGINT"));
155	}
156	
157	startServer();
158

1	import { Request, Response, NextFunction } from "express";
2	import jwt from "jsonwebtoken";
3	import { User, Role } from "./db.js";
4	import db from "./db.js";
5	
6	const JWT_SECRET = process.env.JWT_SECRET || (process.env.NODE_ENV === "production" ? (() => { throw new Error("JWT_SECRET environment variable is required in production"); })() : "dev-secret-change-in-production");
7	const COOKIE_NAME = "nutrishare_token";
8	
9	export interface AuthRequest extends Request {
10	  user?: {
11	    id: number;
12	    email: string;
13	    role: Role;
14	    name: string;
15	    status: string;
16	  };
17	}
18	
19	export function signToken(user: User): string {
20	  return jwt.sign(
21	    { id: user.id, email: user.email, role: user.role, name: user.name, status: user.status },
22	    JWT_SECRET,
23	    { expiresIn: "7d" }
24	  );
25	}
26	
27	export function setAuthCookie(res: Response, token: string) {
28	  res.cookie(COOKIE_NAME, token, {
29	    httpOnly: true,
30	    secure: process.env.NODE_ENV === "production",
31	    sameSite: "lax",
32	    maxAge: 7 * 24 * 60 * 60 * 1000,
33	    path: "/",
34	  });
35	}
36	
37	export function clearAuthCookie(res: Response) {
38	  res.clearCookie(COOKIE_NAME, { path: "/" });
39	}
40	
41	export function authMiddleware(req: AuthRequest, res: Response, next: NextFunction): void {
42	  const token = req.cookies?.[COOKIE_NAME];
43	  if (!token) {
44	    res.status(401).json({ message: "Belum login" });
45	    return;
46	  }
47	  try {
48	    const decoded = jwt.verify(token, JWT_SECRET) as any;
49	    req.user = { id: decoded.id, email: decoded.email, role: decoded.role, name: decoded.name, status: decoded.status };
50	    next();
51	  } catch {
52	    res.status(401).json({ message: "Sesi tidak valid" });
53	  }
54	}
55	
56	export function requireRole(...roles: Role[]) {
57	  return (req: AuthRequest, res: Response, next: NextFunction): void => {
58	    if (!req.user) {
59	      res.status(401).json({ message: "Belum login" });
60	      return;
61	    }
62	    if (!roles.includes(req.user.role as Role)) {
63	      res.status(403).json({ message: "Tidak punya akses" });
64	      return;
65	    }
66	    next();
67	  };
68	}
