1	import { Router } from "express";
2	import multer from "multer";
3	import path from "path";
4	import fs from "fs";
5	import { authMiddleware } from "./auth.js";
6	
7	const uploadRouter = Router();
8	const UPLOAD_DIR = path.join(process.cwd(), "public", "uploads");
9	
10	if (!fs.existsSync(UPLOAD_DIR)) fs.mkdirSync(UPLOAD_DIR, { recursive: true });
11	
12	const storage = multer.diskStorage({
13	  destination: (_req, _file, cb) => cb(null, UPLOAD_DIR),
14	  filename: (_req, file, cb) => {
15	    const ext = path.extname(file.originalname).toLowerCase();
16	    const safe = file.originalname.replace(/[^a-zA-Z0-9_-]/g, "_").slice(0, 50);
17	    cb(null, `${Date.now()}-${safe}${ext}`);
18	  },
19	});
20	
21	const upload = multer({
22	  storage,
23	  limits: { fileSize: 5 * 1024 * 1024 },
24	  fileFilter: (_req, file, cb) => {
25	    const allowed = ["image/jpeg", "image/png", "image/webp"];
26	    if (!allowed.includes(file.mimetype)) {
27	      cb(new Error("File tidak valid. Gunakan JPEG/PNG/WEBP max 5MB."));
28	      return;
29	    }
30	    cb(null, true);
31	  },
32	});
33	
34	uploadRouter.post("/upload", authMiddleware, upload.single("photo"), (req, res) => {
35	  if (!req.file) {
36	    res.status(400).json({ message: "File tidak valid. Gunakan JPEG/PNG/WEBP max 5MB." });
37	    return;
38	  }
39	  res.json({ url: `/uploads/${req.file.filename}` });
40	});
41	
42	export default uploadRouter;
