36	
37	export const registerAdminSchema = z.object({
38	  name: z.string().min(1, "Nama wajib diisi"),
39	  email: z.string().min(1, "Email wajib diisi").email("Email tidak valid"),
40	  password: z.string().min(6, "Password minimal 6 karakter"),
41	  admin_key: z.string().min(1, "Kunci admin wajib diisi"),
42	});
43	
44	export const createDonationSchema = z.object({
45	  food_name: z.string().min(1, "Nama makanan wajib diisi"),
46	  food_type: z.enum(["makanan_berat", "sayur", "lauk_protein", "snack", "minuman", "lainnya"]),
47	  portion_count: z.string().regex(/^\d+$/, "Jumlah porsi harus angka"),
48	  protein_per_portion: z.string().regex(/^\d+(\.\d+)?$/, "Protein harus angka"),
49	  calorie_per_portion: z.string().regex(/^\d+(\.\d+)?$/, "Kalori harus angka"),
50	  hours_valid: z.string().regex(/^\d+$/, "Masa berlaku harus angka"),
51	  pickup_latitude: z.string().min(1, "Latitude wajib diisi"),
52	  pickup_longitude: z.string().min(1, "Longitude wajib diisi"),
53	  notes: z.string().optional().default(""),
54	  iron_mg: z.string().optional(),
55	  vitamin_c_mg: z.string().optional(),
56	});
57	
58	export const claimDonationSchema = z.object({
59	  recipient_id: z.number().int().positive("ID penerima tidak valid").optional(),
60	});
61	
62	export const reviewSchema = z.object({
63	  donation_id: z.number().int().positive(),
64	  donor_id: z.number().int().positive(),
65	  recipient_id: z.number().int().positive(),
66	  rating: z.number().int().min(1, "Rating minimal 1").max(5, "Rating maksimal 5"),
67	  comment: z.string().optional().default(""),
68	});
69	
70	export const adminVerifySchema = z.object({
71	  urgency_score: z.string().optional(),
72	});
73	
74	export const emergencySchema = z.object({
75	  user_id: z.number().int().positive("ID user tidak valid"),
76	});
