78	export function validate(schema: ZodSchema) {
79	  return (req: any, res: any, next: any) => {
80	    const result = schema.safeParse(req.body);
81	    if (!result.success) {
82	      const first: any = result.error.issues[0];
83	      const msg = first.code === "invalid_type"
84	        ? "Field '" + first.path.join(".") + "' wajib diisi"
85	        : first.message;
86	      res.status(400).json({ message: msg });
87	      return;
88	    }
89	    req.body = result.data;
90	    next();
91	  };
92	}
