1	type LogLevel = "debug" | "info" | "warn" | "error";
2	
3	const LOG_LEVELS: Record<LogLevel, number> = {
4	  debug: 0,
5	  info: 1,
6	  warn: 2,
7	  error: 3,
8	};
9	
10	const currentLevel: LogLevel = (process.env.LOG_LEVEL as LogLevel) || (process.env.NODE_ENV === "production" ? "info" : "debug");
11	
12	function shouldLog(level: LogLevel): boolean {
13	  return LOG_LEVELS[level] >= LOG_LEVELS[currentLevel];
14	}
15	
16	function formatMessage(level: LogLevel, message: string, meta?: Record<string, any>): string {
17	  if (process.env.NODE_ENV === "production") {
18	    return JSON.stringify({
19	      timestamp: new Date().toISOString(),
20	      level,
21	      message,
22	      ...meta,
23	    });
24	  }
25	  const metaStr = meta ? ` ${JSON.stringify(meta)}` : "";
26	  return `[${new Date().toISOString()}] [${level.toUpperCase()}] ${message}${metaStr}`;
27	}
28	
29	export const logger = {
30	  debug: (message: string, meta?: Record<string, any>) => {
31	    if (shouldLog("debug")) console.log(formatMessage("debug", message, meta));
32	  },
33	  info: (message: string, meta?: Record<string, any>) => {
34	    if (shouldLog("info")) console.log(formatMessage("info", message, meta));
35	  },
36	  warn: (message: string, meta?: Record<string, any>) => {
37	    if (shouldLog("warn")) console.warn(formatMessage("warn", message, meta));
38	  },
39	  error: (message: string, meta?: Record<string, any>) => {
40	    if (shouldLog("error")) console.error(formatMessage("error", message, meta));
41	  },
42	};
