258	export function initDb(dbPath?: string): Database {
259	  if (db) db.close();
260	  const resolved = dbPath || process.env.DB_PATH || path.join(process.cwd(), "data", "nutrishare.db");
261	  if (process.env.DB_PATH) logger.info(`Using DB_PATH: ${resolved}`);
262	  db = new BetterSqlite3(resolved);
263	  db.pragma("journal_mode = WAL");
264	  db.pragma("foreign_keys = ON");
265	  db.pragma("busy_timeout = 5000");
266	  db.pragma("synchronous = NORMAL");
267	  db.exec(SCHEMA);
268	  // Add reset token columns if they don't exist (migration)
269	  try { db.exec("ALTER TABLE users ADD COLUMN reset_token TEXT"); } catch {}
270	  try { db.exec("ALTER TABLE users ADD COLUMN reset_token_expiry TEXT"); } catch {}
271	  // Activity logs table
272	  try { db.exec("CREATE TABLE IF NOT EXISTS activity_logs (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL, action TEXT NOT NULL, details TEXT, created_at TEXT NOT NULL)"); } catch {}
273	  return db;
274	}
