283	    DELETE FROM notifications;
284	    DELETE FROM claims;
285	    DELETE FROM topsis_results;
286	    DELETE FROM donations;
287	    DELETE FROM recipient_profiles;
288	    DELETE FROM donor_profiles;
289	    DELETE FROM users;
290	  `);
291	}
