1	import { useState, useEffect, useRef } from "react";
2	
3	export function useHideOnScroll() {
4	  const [navVisible, setNavVisible] = useState(true);
5	  const [isScrolled, setIsScrolled] = useState(false);
6	  const lastScroll = useRef(0);
7	
8	  useEffect(() => {
9	    const handle = () => {
10	      const current = window.scrollY;
11	      setNavVisible(current < lastScroll.current || current < 10);
12	      setIsScrolled(current > 20);
13	      lastScroll.current = current;
14	    };
15	    window.addEventListener("scroll", handle, { passive: true });
16	    return () => window.removeEventListener("scroll", handle);
17	  }, []);
18	
19	  return { navVisible, isScrolled };
20	}
