3	export interface ValidationResult {
4	  valid: boolean;
5	  message?: string;
6	}
7	
8	export function validateEmail(email: string): ValidationResult {
9	  if (!email) return { valid: false, message: "Email wajib diisi" };
10	  if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) return { valid: false, message: "Format email tidak valid" };
11	  return { valid: true };
12	}
13	
14	export function validatePassword(password: string): ValidationResult {
15	  if (!password) return { valid: false, message: "Password wajib diisi" };
16	  if (password.length < 6) return { valid: false, message: "Password minimal 6 karakter" };
17	  return { valid: true };
18	}
19	
20	export function validateRequired(value: string, fieldName: string): ValidationResult {
21	  if (!value || !value.trim()) return { valid: false, message: `${fieldName} wajib diisi` };
22	  return { valid: true };
23	}
24	
25	export function validateNumber(value: string, fieldName: string): ValidationResult {
26	  if (!value) return { valid: false, message: `${fieldName} wajib diisi` };
27	  if (isNaN(Number(value)) || Number(value) <= 0) return { valid: false, message: `${fieldName} harus angka positif` };
28	  return { valid: true };
29	}
