12	interface AuthContextType {
13	  user: User | null;
14	  profile: any;
15	  loading: boolean;
16	  login: (email: string, password: string) => Promise<any>;
17	  logout: () => Promise<void>;
18	  refresh: () => Promise<void>;
19	}
20	
21	const AuthContext = createContext<AuthContextType>(null!);
22	
23	export function AuthProvider({ children }: { children: ReactNode }) {
24	  const [user, setUser] = useState<User | null>(null);
25	  const [profile, setProfile] = useState<any>(null);
26	  const [loading, setLoading] = useState(true);
27	
28	  const refresh = async () => {
29	    try {
30	      const res = await api.fetchJSON("/api/auth/me");
31	      setUser(res.user);
32	      setProfile(res.profile);
33	    } catch {
34	      setUser(null);
35	      setProfile(null);
36	    }
37	  };
38	
39	  useEffect(() => {
40	    refresh().finally(() => setLoading(false));
41	  }, []);
42	
43	  const login = async (email: string, password: string) => {
44	    const res = await api.fetchJSON("/api/auth/login", {
45	      method: "POST",
46	      headers: { "Content-Type": "application/json" },
47	      body: JSON.stringify({ email, password }),
48	    });
49	    setUser(res.user);
50	    setProfile(res.profile);
51	    return res;
52	  };
53	
54	  const logout = async () => {
55	    await api.fetchJSON("/api/auth/logout", { method: "POST" });
56	    setUser(null);
57	    setProfile(null);
58	  };
59	
60	  return (
61	    <AuthContext.Provider value={{ user, profile, loading, login, logout, refresh }}>
62	      {children}
63	    </AuthContext.Provider>
64	  );
65	}
66	
67	export function useAuth() {
68	  return useContext(AuthContext);
