1	import { useState, useEffect } from "react";
2	
3	type Theme = "light" | "dark";
4	
5	export function useTheme() {
6	  const [theme, setTheme] = useState<Theme>(() => {
7	    if (typeof window === "undefined") return "light";
8	    const stored = localStorage.getItem("nutrishare-theme");
9	    if (stored === "dark" || stored === "light") return stored;
10	    return window.matchMedia("(prefers-color-scheme: dark)").matches ? "dark" : "light";
11	  });
12	
13	  useEffect(() => {
14	    const root = document.documentElement;
15	    if (theme === "dark") {
16	      root.classList.add("dark");
17	    } else {
18	      root.classList.remove("dark");
19	    }
20	    localStorage.setItem("nutrishare-theme", theme);
21	  }, [theme]);
22	
23	  const toggle = () => setTheme(t => (t === "light" ? "dark" : "light"));
24	
25	  return { theme, toggle };
26	}
