1	import { useEffect, useRef, useCallback } from "react";
2	
3	export function useSSE(userId: number | undefined, onNotification: (data: any) => void) {
4	  const lastEventRef = useRef<string>("");
5	  const cbRef = useRef(onNotification);
6	  cbRef.current = onNotification;
7	
8	  useEffect(() => {
9	    if (!userId) return;
10	    let eventSource: EventSource | null = null;
11	    let reconnectTimer: ReturnType<typeof setTimeout>;
12	
13	    const connect = () => {
14	      if (eventSource) eventSource.close();
15	      eventSource = new EventSource(`/api/notifications/subscribe?user_id=${userId}`);
16	
17	      eventSource.onmessage = (e) => {
18	        if (e.data === "connected") return;
19	        if (e.data === lastEventRef.current) return; // dedup
20	        lastEventRef.current = e.data;
21	        try {
22	          const data = JSON.parse(e.data);
23	          cbRef.current(data);
24	        } catch { /* ignore ping */ }
25	      };
26	
27	      eventSource.onerror = () => {
28	        eventSource?.close();
29	        reconnectTimer = setTimeout(connect, 5000);
30	      };
31	    };
32	
33	    connect();
34	    return () => {
35	      eventSource?.close();
36	      clearTimeout(reconnectTimer);
37	    };
38	  }, [userId]);
39	}
