1	import sharp from "sharp";
2	import fs from "fs";
3	import path from "path";
4	
5	const INPUT_DIR = path.join(process.cwd(), "src", "assets", "images");
6	const OUTPUT_DIR = path.join(process.cwd(), "src", "assets", "images");
7	
8	async function compressImages() {
9	  if (!fs.existsSync(INPUT_DIR)) {
10	    console.log("No images directory found");
11	    return;
12	  }
13	
14	  const files = fs.readdirSync(INPUT_DIR);
15	  const imageFiles = files.filter(f => /\.(jpg|jpeg|png)$/i.test(f));
16	
17	  console.log(`Found ${imageFiles.length} images to compress`);
18	
19	  for (const file of imageFiles) {
20	    const inputPath = path.join(INPUT_DIR, file);
21	    const outputPath = path.join(OUTPUT_DIR, file.replace(/\.(jpg|jpeg|png)$/i, ".webp"));
22	
23	    try {
24	      await sharp(inputPath)
25	        .webp({ quality: 80 })
26	        .toFile(outputPath);
27	
28	      const originalSize = fs.statSync(inputPath).size;
29	      const newSize = fs.statSync(outputPath).size;
30	      const savings = ((originalSize - newSize) / originalSize * 100).toFixed(1);
31	
32	      console.log(`✓ ${file} → ${path.basename(outputPath)} (${savings}% smaller)`);
33	
34	      // Remove original file
35	      fs.unlinkSync(inputPath);
36	    } catch (err) {
37	      console.error(`✗ Failed to compress ${file}:`, err.message);
38	    }
39	  }
40	
41	  console.log("\nCompression complete!");
42	}
43	
44	compressImages();
